const TABLES = Object.freeze({
  2026: Object.freeze({
    percentageTables: PERCENTAGE_TABLES,
    sources: Object.freeze([
      "NM Taxation and Revenue Department, FYI-104 New Mexico Withholding Tax (Rev. 11/2025, effective Jan. 1, 2026): https://realfile.tax.newmexico.gov/FYI-104.pdf",
    ]),
  }),
});

function validateForm(form) {
  if (!onFile(form)) return;
  const c = formChecker("New Mexico copy of Form W-4");
  c.oneOf(form, "filingStatus", ["single", "married", "headOfHousehold"]);
  c.cents(form, "additionalWithholdingCents");
}

function compute({ taxYear, wagesCents, payPeriodsPerYear, form, federalW4 = null }) {
  const t = TABLES[taxYear];
  validateForm(form);
  const period = PERIOD_BY_COUNT[payPeriodsPerYear];
  if (!period) throw new Error(`New Mexico has no withholding table for ${payPeriodsPerYear} pay periods a year`);
  let status = "single";
  let formBasis = "none-on-file-single";
  if (onFile(form)) {
    status = form.filingStatus;
    formBasis = "new-mexico-w4-copy";
  } else if (federalW4) {
    if (federalW4.formYear >= 2020) {
      status = federalW4.filingStatus === "marriedFilingJointly" ? "married" : federalW4.filingStatus === "headOfHousehold" ? "headOfHousehold" : "single";
    } else {
      status = federalW4.maritalStatus === "married" ? "married" : "single";
    }
    formBasis = "federal-w4";
  }
  const tax = fromBaseTable(wagesCents, t.percentageTables[period][status]);
  const extra = onFile(form) ? form.additionalWithholdingCents ?? 0 : 0;
  return { stateCents: Math.round(tax) + extra, formBasis, lines: { period, status } };
}

module.exports = {
  code: "NM",
  name: "New Mexico",
  wageBasis: "federal-income-tax-wages",
  years: Object.keys(TABLES).map(Number),
  TABLES,
  validateForm,
  compute,
};
